Here is the commit message:
misc: pci_endpoint_test: Prevent some integer overflows

"size + max" can have an arithmetic overflow when we're allocating:

	orig_src_addr = dma_alloc_coherent(dev, size + alignment, ...

I've added a few checks to prevent that.

Fixes: 13107c60681f ("misc: pci_endpoint_test: Add support to provide aligned buffer addresses")
Signed-off-by: Dan Carpenter <dan.carpenter@oracle.com>
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>

Here is the root cause:
The bug is caused by the potential for an arithmetic overflow when calculating the total size for memory allocation in the `dma_alloc_coherent` function. Specifically, the expression `size + alignment` can exceed the maximum value representable by the `size_t` type, leading to incorrect memory allocation and possible undefined behavior.

Here is the patch:

 static bool pci_endpoint_test_copy(struct pci_endpoint_test *test, size_t size)
 {
 	bool ret = false;
 	void *src_addr;
 	void *dst_addr;
 	dma_addr_t src_phys_addr;
 	dma_addr_t dst_phys_addr;
 	struct pci_dev *pdev = test->pdev;
 	struct device *dev = &pdev->dev;
 	void *orig_src_addr;
 	dma_addr_t orig_src_phys_addr;
 	void *orig_dst_addr;
 	dma_addr_t orig_dst_phys_addr;
 	size_t offset;
 	size_t alignment = test->alignment;
 	u32 src_crc32;
 	u32 dst_crc32;

+	if (size > SIZE_MAX - alignment)
+		goto err;
+
 	orig_src_addr = dma_alloc_coherent(dev, size + alignment,
 					   &orig_src_phys_addr, GFP_KERNEL);
 	if (!orig_src_addr) {
 		dev_err(dev, "failed to allocate source buffer\n");
 		ret = false;
 		goto err;
 	}

 	if (alignment && !IS_ALIGNED(orig_src_phys_addr, alignment)) {
 		src_phys_addr = PTR_ALIGN(orig_src_phys_addr, alignment);
 		offset = src_phys_addr - orig_src_phys_addr;
 		src_addr = orig_src_addr + offset;
 	} else {
 		src_phys_addr = orig_src_phys_addr;
 		src_addr = orig_src_addr;
 	}

 	pci_endpoint_test_writel(test, PCI_ENDPOINT_TEST_LOWER_SRC_ADDR,
 				 lower_32_bits(src_phys_addr));

 	pci_endpoint_test_writel(test, PCI_ENDPOINT_TEST_UPPER_SRC_ADDR,
 				 upper_32_bits(src_phys_addr));

 	get_random_bytes(src_addr, size);
 	src_crc32 = crc32_le(~0, src_addr, size);

 	orig_dst_addr = dma_alloc_coherent(dev, size + alignment,
 					   &orig_dst_phys_addr, GFP_KERNEL);
 	if (!orig_dst_addr) {
 		dev_err(dev, "failed to allocate destination address\n");
 		ret = false;
 		goto err_orig_src_addr;
 	}

 	if (alignment && !IS_ALIGNED(orig_dst_phys_addr, alignment)) {
 		dst_phys_addr = PTR_ALIGN(orig_dst_phys_addr, alignment);
 		offset = dst_phys_addr - orig_dst_phys_addr;
 		dst_addr = orig_dst_addr + offset;
 	} else {
 		dst_phys_addr = orig_dst_phys_addr;
 		dst_addr = orig_dst_addr;
 	}

 	pci_endpoint_test_writel(test, PCI_ENDPOINT_TEST_LOWER_DST_ADDR,
 				 lower_32_bits(dst_phys_addr));
 	pci_endpoint_test_writel(test, PCI_ENDPOINT_TEST_UPPER_DST_ADDR,
 				 upper_32_bits(dst_phys_addr));

 	pci_endpoint_test_writel(test, PCI_ENDPOINT_TEST_SIZE,
 				 size);

 	pci_endpoint_test_writel(test, PCI_ENDPOINT_TEST_COMMAND,
 				 1 << MSI_NUMBER_SHIFT | COMMAND_COPY);

 	wait_for_completion(&test->irq_raised);

 	dst_crc32 = crc32_le(~0, dst_addr, size);
 	if (dst_crc32 == src_crc32)
 		ret = true;

 	dma_free_coherent(dev, size + alignment, orig_dst_addr,
 			  orig_dst_phys_addr);

 err_orig_src_addr:
 	dma_free_coherent(dev, size + alignment, orig_src_addr,
 			  orig_src_phys_addr);

 err:
 	return ret;
 }

